PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, source_type TEXT NOT NULL, uri TEXT, external_id TEXT, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS source_external ON sources(source_type,external_id) WHERE external_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS source_snapshots(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), hash TEXT NOT NULL, raw BLOB NOT NULL, captured_at TEXT NOT NULL, UNIQUE(source_id,hash));
CREATE TRIGGER IF NOT EXISTS snapshot_immutable_update BEFORE UPDATE ON source_snapshots BEGIN SELECT RAISE(ABORT,'Source snapshots are immutable'); END;
CREATE TRIGGER IF NOT EXISTS snapshot_immutable_delete BEFORE DELETE ON source_snapshots BEGIN SELECT RAISE(ABORT,'Source snapshots are immutable'); END;
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, snapshot_id TEXT NOT NULL REFERENCES source_snapshots(id), title TEXT NOT NULL, external_id TEXT, capture_status TEXT NOT NULL, warnings TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), external_id TEXT, parent_id TEXT, role TEXT NOT NULL, content TEXT NOT NULL, position INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS message_conversation ON messages(conversation_id,position);
CREATE TABLE IF NOT EXISTS question_memories(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), original_question TEXT NOT NULL, normalized_question TEXT NOT NULL, summary TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memory_messages(memory_id TEXT NOT NULL REFERENCES question_memories(id), message_id TEXT NOT NULL REFERENCES messages(id), span_start INTEGER NOT NULL DEFAULT 0, span_end INTEGER NOT NULL, position INTEGER NOT NULL, PRIMARY KEY(memory_id,message_id));
CREATE TABLE IF NOT EXISTS cards(id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources(id), conversation_id TEXT REFERENCES conversations(id), card_type TEXT NOT NULL, title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '[]', color TEXT NOT NULL DEFAULT 'lavender', current_revision_id TEXT REFERENCES card_revisions(id), knowledge_status TEXT NOT NULL DEFAULT 'unverified', favorite INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_reviewed_at TEXT);
CREATE INDEX IF NOT EXISTS cards_updated ON cards(archived,updated_at DESC);
CREATE TABLE IF NOT EXISTS card_revisions(id TEXT PRIMARY KEY, card_id TEXT NOT NULL REFERENCES cards(id), title TEXT NOT NULL, summary TEXT NOT NULL, tags TEXT NOT NULL, content TEXT NOT NULL, author_type TEXT NOT NULL, parent_revision_id TEXT REFERENCES card_revisions(id), status TEXT NOT NULL, instruction TEXT, model TEXT, prompt_version TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS card_links(source_card_id TEXT NOT NULL REFERENCES cards(id), target_card_id TEXT NOT NULL REFERENCES cards(id), relation_type TEXT NOT NULL DEFAULT 'related', status TEXT NOT NULL DEFAULT 'accepted', PRIMARY KEY(source_card_id,target_card_id), CHECK(source_card_id<>target_card_id));
CREATE TABLE IF NOT EXISTS knowledge_documents(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), snapshot_id TEXT NOT NULL REFERENCES source_snapshots(id), title TEXT NOT NULL, filename TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_chunks(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES knowledge_documents(id), text TEXT NOT NULL, locator TEXT NOT NULL, position INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS evidence(id TEXT PRIMARY KEY, card_id TEXT NOT NULL REFERENCES cards(id), chunk_id TEXT NOT NULL REFERENCES knowledge_chunks(id), claim_ref TEXT NOT NULL, verdict TEXT NOT NULL DEFAULT 'reference', created_at TEXT NOT NULL, UNIQUE(card_id,chunk_id));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, job_type TEXT NOT NULL, status TEXT NOT NULL, progress INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, input TEXT NOT NULL, result TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS job_queue ON jobs(status,created_at);
CREATE TABLE IF NOT EXISTS audit_findings(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), target_id TEXT NOT NULL REFERENCES cards(id), finding_type TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, related_id TEXT, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approval_requests(id TEXT PRIMARY KEY, action_type TEXT NOT NULL, target_id TEXT NOT NULL, revision_id TEXT REFERENCES card_revisions(id), status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operation_logs(id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT, detail TEXT NOT NULL DEFAULT '{}', timestamp TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS embeddings(card_id TEXT PRIMARY KEY REFERENCES cards(id), revision_id TEXT NOT NULL, model TEXT NOT NULL, vector TEXT NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS card_fts USING fts5(card_id UNINDEXED,title,summary,content,questions,tokenize='trigram');
CREATE INDEX IF NOT EXISTS snapshot_hash ON source_snapshots(hash);
CREATE INDEX IF NOT EXISTS card_source ON cards(source_id);
CREATE INDEX IF NOT EXISTS memory_conversation ON question_memories(conversation_id);
CREATE INDEX IF NOT EXISTS revision_card ON card_revisions(card_id,created_at DESC);
CREATE INDEX IF NOT EXISTS chunk_document ON knowledge_chunks(document_id,position);
CREATE TABLE IF NOT EXISTS snapshot_origins(snapshot_id TEXT PRIMARY KEY REFERENCES source_snapshots(id),original_snapshot_id TEXT NOT NULL REFERENCES source_snapshots(id));
CREATE TABLE IF NOT EXISTS message_metadata(message_id TEXT PRIMARY KEY REFERENCES messages(id),data TEXT NOT NULL);
